from __future__ import annotations

import grp
import os
import re
import subprocess
import sys
from pathlib import Path

from . import settings
from .fleet_xml import FleetConfig, FleetXml
from .ports import is_loopback, mapping_address
from .resources import COMPOSE as _COMPOSE_PACKAGE, packaged_path, stack_fleet

# Every shipped stack is generated by `qemu-tool gen-compose` from the fleet
# file of the same name in qemu/stacks/.
_STACKS = ("rocm-golden", "helios-tray", "mi355x-server")
_DEFAULT_STACK = "rocm-golden"

# Names a rendered stack directory for every compose command in this shell,
# so a fleet is selected once instead of on every invocation. Mirrors
# $QEMU_TOOL_FLEET in FleetXml.find(); never consulted by gen-compose, where
# the output directory has to stay a typed decision.
_STACK_DIR_ENV = "QEMU_TOOL_STACK"

# Installed location (Debian package).
_INSTALLED_COMPOSE_ROOT = Path("/usr/share/qemu-tool/compose")

# Source-tree fallback: three levels up from this file is qemu/, one more is
# the repo root, then qemu/compose/<stack>/
_SOURCE_COMPOSE_ROOT = Path(__file__).parent.parent.parent / "qemu" / "compose"


def _compose_dir(stack: str) -> Path:
    installed = _INSTALLED_COMPOSE_ROOT / stack
    if installed.is_dir():
        return installed
    source = _SOURCE_COMPOSE_ROOT / stack
    if source.is_dir():
        return source
    # Last resort: the copy inside the wheel, which is all a pipx install has.
    packaged = packaged_path(_COMPOSE_PACKAGE, stack)
    if packaged is not None and packaged.is_dir():
        return packaged
    raise FileNotFoundError(
        f"Compose stack '{stack}' not found at {installed} or {source}, "
        f"and not bundled with this install. "
        f"Available stacks: {', '.join(_STACKS)}"
    )


def _stack_dir(stack_dir: Path, source: str = "--stack-dir") -> Path:
    cdir = stack_dir.expanduser()
    compose_file = cdir / "docker-compose.yml"
    if not compose_file.is_file():
        sys.exit(
            f"Error: no docker-compose.yml in {source} {cdir}.\n"
            f"       Looked for: {compose_file}\n"
            "       Generate one with: qemu-tool gen-compose --output-dir "
            f"{cdir}"
        )
    return cdir


def _is_rendered_stack(cdir: Path) -> bool:
    """Is this directory one gen-compose rendered?

    The provenance header is the identity test, not the mere presence of a
    docker-compose.yml: without it, running qemu-tool from any unrelated
    docker project directory would adopt that project as "the stack".
    """
    from . import gen_compose

    compose_file = cdir / "docker-compose.yml"
    return compose_file.is_file() and gen_compose.recorded_digest(compose_file) is not None


def _discover_stack_dir(stack: str | None) -> Path | None:
    """The rendered stack to drive when no --stack-dir was passed, or None.

    $QEMU_TOOL_STACK first -- the same shape as $QEMU_TOOL_FLEET in
    FleetXml.find(), and what lets a fleet be selected once per shell instead
    of on every command. Then the cwd, if it is itself a rendered stack, the
    way docker compose picks up the compose.yaml beside you.

    An identity test on one directory, never a walk-up. docker compose can
    walk up safely because what it finds is what it runs; here a walk-up from
    anywhere inside this checkout would reach qemu/compose/<default>/ and
    drive the committed default stack under the name of a 32-VM fleet, which is
    the silent substitution --stack-dir was added to prevent.
    """
    if stack is not None:
        # A named stack is a choice the user typed; nothing ambient outranks it.
        return None
    raw = os.environ.get(_STACK_DIR_ENV)
    if raw:
        return _stack_dir(Path(raw), source=f"${_STACK_DIR_ENV}")
    cwd = Path.cwd()
    if _is_rendered_stack(cwd):
        return cwd
    return None


def _same_file(a: Path, b: Path) -> bool:
    try:
        return a.resolve() == b.resolve()
    except OSError:
        return False


def _warn_if_stale(cdir: Path, layers: list[Path], stack: str | None,
                   explicit: bool = True) -> None:
    """Warn, never block, when the generated YAML predates the settings layers.

    Blocking would be wrong: `down` against a stale tree is exactly how you
    recover from a bad edit, and `logs`/`ps` have to keep working too.

    `stack` names a shipped stack, None for a rendered directory. A shipped
    stack is rendered from qemu/stacks/<stack>.xml and nothing else, so only
    that file can make it stale: any other layers are a different fleet, and
    a hint to regenerate from them would render that fleet over the shipped
    stack. `explicit` is False for layers the search path found; nobody
    chose those against this stack, so they are not reported at all.
    """
    from . import gen_compose

    recorded = gen_compose.recorded_digest(cdir / "docker-compose.yml")
    if recorded is None:
        return
    # Against the digest of all the layers, not the first one: an overlay is
    # as much an input to the render as the golden file it sits on, so an
    # edit to either has to read as stale.
    if recorded == gen_compose.xml_digest(layers):
        return
    # From the RESOLVED layers, not the raw command line: a regenerate hint
    # that does not regenerate is worth less than no hint.
    arg = "".join(f" --xml {p}" for p in layers)
    names = ", ".join(str(p) for p in layers)
    if stack is not None:
        own = stack_fleet(stack)
        if not (len(layers) == 1 and own is not None
                and _same_file(layers[0], own)):
            if explicit:
                print(
                    f"Warning: {cdir / 'docker-compose.yml'} is the shipped "
                    f"{stack} stack, rendered from "
                    f"{own or f'stacks/{stack}.xml'}, not from {names}.\n"
                    "         Guest count and names come from the render, "
                    "not from these settings.\n"
                    "         To run these settings: qemu-tool gen-compose "
                    f"--output-dir DIR{arg}\n"
                    "                                qemu-tool compose "
                    f"--stack-dir DIR{arg} ...",
                    file=sys.stderr,
                )
            return
    target = f" --stack {stack}" if stack is not None else f" --output-dir {cdir}"
    print(
        f"Warning: {cdir / 'docker-compose.yml'} was generated from a different "
        f"version of {names}.\n"
        f"         Regenerate with: qemu-tool gen-compose{target}{arg}",
        file=sys.stderr,
    )


# Directories a stack bind-mounts and writes into. Each one belongs to
# whoever ran the fleet, and each is created by the Docker daemon -- as root,
# 0755 -- if it does not exist when the service starts. Creating them here
# first is what makes that moot. Container target, and the element naming it.
_DATA_DIRS = {
    "/prometheus": "prom-data-dir",
    "/loki": "loki-data-dir",
    "/var/lib/grafana": "grafana-data-dir",
}
_DATA_DIR_RE = re.compile(
    r'^\s*-\s+"?(/[^:"]+):(' + "|".join(map(re.escape, _DATA_DIRS)) + r')"?\s*$'
)

# Any bind mount: host side, container side. Used to find a mount that lands
# INSIDE one of the data directories above.
_VOLUME_RE = re.compile(
    r'^\s*-\s+"?([^:"\s]+):(/[^:"\s]+)(?::[a-z,]+)?"?\s*$'
)

# Subcommands that actually start containers. `ps`, `logs` and `down` must
# keep working against a stack whose artifacts are in any state at all --
# `down` especially, since recovering from a bad run is exactly when the
# checks below would otherwise be in the way.
_STARTING = frozenset({"up", "start", "run", "create"})

# Subcommands that tear the whole project down. These get every profile
# enabled, and are checked afterwards for survivors.
#
# WHY: a fleet was reported with prometheus, grafana and the stats exporter
# still running 41 hours after a `down --remove-orphans` that completed
# successfully.
#
# The obvious explanation -- that profile-gated services are filtered out of
# `down` -- is WRONG, and was tested rather than assumed: on compose v5.3.1,
# `up --profile metrics` followed by a plain `down`, `down --remove-orphans`
# or `stop` removes the gated container every time. So that is not the
# mechanism, and the real one is not established. The likeliest remaining
# candidate is a project-name mismatch: compose derives the name from the
# working directory, `compose.run` never passes `-p`, and the stack-directory
# discovery order (--stack-dir, then $QEMU_TOOL_STACK, then the cwd) can
# resolve differently between the `up` and the `down` -- in which case the
# down tears down an empty project and reports success.
#
# `--profile "*"` is therefore belt-and-braces, not the fix: it costs nothing,
# makes `down` unambiguous, and would cover the filtered-out theory if some
# other compose version does behave that way. The survivor check below is the
# part that actually catches this, whatever causes it.
_TEARDOWN = frozenset({"down", "stop"})


def _caller_identity() -> dict[str, str]:
    """CONTAINER_USER and CONTAINER_KVM_GID for whoever ran this command.

    The whole point of the setting is that the containers run as the person
    who started them, and the overwhelmingly common answer to "which uid" is
    "mine". Requiring that to be typed into a settings file made root the
    practical default for years, because the value cannot be committed (it
    differs per host) and so there was nowhere obvious to put it.

    getuid()/getgid(), not getlogin() or $USER: those answer "who owns the
    terminal", which is a different question the moment this runs under sudo,
    a systemd unit or CI.
    """
    ident = {"CONTAINER_USER": f"{os.getuid()}:{os.getgid()}"}
    # The gid that owns /dev/kvm, asked of the device itself first. The group
    # is conventionally called "kvm" and conventionally is the owner, but the
    # question the qemu container actually needs answered is "which gid opens
    # this node" -- and a host can have the group without the device, or the
    # device without that name. The name is the fallback, not the source.
    try:
        ident["CONTAINER_KVM_GID"] = str(os.stat("/dev/kvm").st_gid)
    except OSError:
        try:
            ident["CONTAINER_KVM_GID"] = str(grp.getgrnam("kvm").gr_gid)
        except KeyError:
            # Neither. Left unset, so compose refuses rather than starting a
            # fleet that silently falls back to TCG and runs ~20x slower --
            # which presents as "the guests are hanging", not as a missing
            # group. A host with no /dev/kvm cannot run this stack anyway.
            pass
    return ident


# Applied to whatever value is actually in force, which may have come from
# the environment and so have been seen by nothing else.
_UID_GID_RE = re.compile(r"[0-9]+:[0-9]+")


def _reject_bad_user(value: str, source: str) -> None:
    """Refuse a CONTAINER_USER that cannot work, naming where it came from.

    Every way of getting this wrong fails a long way from the thing that set
    it, and one of them does not fail at all:

    * A name ("stebates"). Docker resolves it against the IMAGE's /etc/passwd,
      which carries no entry for your uid, and dies at container create with
      "unable to find user".
    * A bare uid ("1000"). Docker then wants the gid from that uid's passwd
      entry, which does not exist either.
    * "${UID}:${GID}", the spelling people try first and the worst of the
      three. Bash exports neither, so it survives as literal text, compose
      substitutes empty for both, and `user: ":"` runs as root without
      erroring.

    Checked here rather than at render time: a stack is rendered once and run
    many times, and the value arrives through the environment of each run.
    """
    if _UID_GID_RE.fullmatch(value.strip()):
        return
    sys.exit(
        f"Error: CONTAINER_USER must be numeric <uid>:<gid>, got {value!r}\n"
        f"       (from {source}).\n"
        "       A user name does not resolve: the images carry no passwd "
        "entry for your uid.\n"
        "       ${UID}:${GID} does not work either -- bash exports neither, "
        "so it silently becomes root.\n"
        "       Use the literal ids, e.g. CONTAINER_USER=$(id -u):$(id -g) "
        "evaluated by your shell,\n"
        "       or unset it and qemu-tool will fill in your own."
    )


def interpolation_vars(cfg: FleetConfig) -> dict[str, str]:
    """The ${VAR} names docker compose interpolates, valued from fleet XML.

    This is docker compose's interface, not a settings format: a compose file
    can only be parameterised through variables, so this is the one place
    FleetConfig is spelled that way. A generated stack bakes everything else
    in at gen-compose time; tests/test_compose_interpolation.py holds this to
    the names the shipped stacks actually interpolate.
    """
    return {
        "VM_IMAGES_DIR": cfg.vm_images_dir,
        "QEMU_TOOL_SRC": cfg.qemu_tool_src,
    }


def interpolation_env(fleet: FleetConfig | None, env: dict[str, str]) -> None:
    """Add the fleet's interpolation variables to a child-process environment.

    Only a name `env` does not already carry is filled in. That is compose's
    own precedence -- the process environment outranks every other source --
    so a variable exported in the shell, or set from a flag before this is
    called, still wins. Present-but-empty counts as set, as it does to compose.
    """
    if fleet is None:
        return
    for key, value in interpolation_vars(fleet).items():
        env.setdefault(key, value)
    # With settings in force, a stray <stack dir>/.env must not also be
    # consulted for the names the fleet leaves unset.
    env.setdefault("COMPOSE_DISABLE_ENV_FILE", "1")


def resolve_identity() -> tuple[dict[str, str], str]:
    """The uid:gid the containers will really run as, and where it came from.

    The process environment first, then the caller's own ids: anything set in
    the environment is already a decision, and it is what compose itself
    would resolve.

    Returns the full pair plus a human-readable source for CONTAINER_USER, so
    a caller can say which answer it got rather than just printing a number.
    """
    ident = dict(_caller_identity())
    source = "this user"
    for key in ("CONTAINER_USER", "CONTAINER_KVM_GID"):
        if os.environ.get(key, "").strip():
            ident[key] = os.environ[key]
            if key == "CONTAINER_USER":
                source = "the environment"
    _reject_bad_user(ident["CONTAINER_USER"], source)
    return ident, source


def _apply_identity(env: dict[str, str]) -> None:
    """Fill in CONTAINER_USER/CONTAINER_KVM_GID, without overriding a choice.

    Only a key nobody has expressed an opinion about is filled in.
    resolve_identity decides what the answer is and refuses an unusable one
    -- this only decides whether to write it down.
    """
    ident, _ = resolve_identity()
    for key, value in ident.items():
        if os.environ.get(key, "").strip():
            continue
        env[key] = value


def _all_profiles_for_teardown(compose_args: list[str]) -> list[str]:
    """`--profile "*"` when tearing down, unless profiles were named.

    Returns the global flags to insert, which is either that or nothing.

    Respecting an explicit choice matters: `down --profile metrics` is
    someone scoping the teardown deliberately, and overriding it would make
    the flag a lie. COMPOSE_PROFILES counts as naming them too, for the same
    reason -- it is how compose itself is told, and a tool that ignored it
    would disagree with a plain `docker compose` run beside it.

    Only the project-wide form. `down` and `stop` with service names after
    them already say exactly what to act on, and widening the profile set
    there changes nothing.
    """
    if not any(a in _TEARDOWN for a in compose_args):
        return []
    if any(a == "--profile" or a.startswith("--profile=") for a in compose_args):
        return []
    if os.environ.get("COMPOSE_PROFILES", "").strip():
        return []
    return ["--profile", "*"]


def _warn_about_survivors(globals_: list[str], cdir: Path,
                          env: dict[str, str]) -> None:
    """Say so when a teardown reported success and left containers running.

    This is the check that catches the reported failure -- three containers
    alive 41 hours after a successful `down --remove-orphans` -- WITHOUT
    needing to know why. A teardown that exits 0 while its own project still
    has running containers is wrong whatever the cause, and nothing said so.

    Asked through compose with the same global flags the teardown used, so
    the project name resolves identically. Reimplementing compose's rule
    (directory basename, lowercased, punctuation stripped) would be a second
    source of truth and could disagree with the command it is checking --
    which is the very class of bug this is here to find.

    Never changes the exit status. The teardown did what it was asked; this
    reports a fact about the result, and a `down` that started failing
    because of a container somebody else's project left behind would be
    worse than the problem.
    """
    try:
        listed = subprocess.run(
            globals_ + ["ps", "--format", "{{.Name}}"],
            cwd=cdir, env=env, capture_output=True, text=True, timeout=30,
        )
    except (OSError, subprocess.SubprocessError):
        return
    names = [n for n in listed.stdout.split() if n.strip()]
    if not names:
        return
    print(
        f"\nWarning: the teardown succeeded but {len(names)} container(s) in "
        "this project are still running:",
        file=sys.stderr,
    )
    for name in names:
        print(f"           {name}", file=sys.stderr)
    print(
        "         A stack brought up from a different directory resolves to a "
        "different\n"
        "         compose project, and a teardown of the wrong one reports "
        "success. Check\n"
        "         --stack-dir / $QEMU_TOOL_STACK, or remove them by name with "
        "`docker rm -f`.",
        file=sys.stderr,
    )


def _data_dirs(cdir: Path) -> list[tuple[str, Path]]:
    """(element, path) for each data directory the rendered stack mounts.

    Read back from the compose file rather than from the settings: the
    render supplies a default for an element the fleet leaves unset, and a
    rendered stack is driven with no settings at all, so the file is the only
    place that says what Docker will really mount.
    """
    try:
        lines = (cdir / "docker-compose.yml").read_text().splitlines()
    except OSError:
        return []
    found: dict[str, Path] = {}
    for line in lines:
        match = _DATA_DIR_RE.match(line)
        if match:
            found.setdefault(_DATA_DIRS[match.group(2)], Path(match.group(1)))
    return list(found.items())


def _nested_mount_points(cdir: Path) -> list[Path]:
    """Host directories the runtime would create inside a data directory.

    Grafana's dashboards are mounted at /var/lib/grafana/dashboards, which is
    inside the <grafana-data-dir> bind mount. The container runtime makes a
    missing mount point itself, as root, and through the bind mount that
    directory appears on the host: `grafana-data/dashboards`, root:root 0755,
    in a directory this file otherwise promises is the caller's. It stopped
    nothing, but it is a root-owned path in a stack that needs no root, and
    one a non-empty copy of would need sudo to remove.
    """
    try:
        lines = (cdir / "docker-compose.yml").read_text().splitlines()
    except OSError:
        return []
    hosts: dict[str, Path] = {}
    for line in lines:
        match = _DATA_DIR_RE.match(line)
        if match:
            hosts.setdefault(match.group(2), Path(match.group(1)))
    found: list[Path] = []
    for line in lines:
        match = _VOLUME_RE.match(line)
        if not match:
            continue
        inside = match.group(2)
        for target, host in hosts.items():
            if inside.startswith(target + "/"):
                point = host / inside[len(target) + 1:]
                if point not in found:
                    found.append(point)
    return found


_SERVICE_RE = re.compile(r"^  ([A-Za-z0-9][A-Za-z0-9_.-]*):\s*$")
_PORT_ENTRY_RE = re.compile(r"""^\s+-\s+["']?([^"'\s#]+)["']?\s*$""")


def published_ports(text: str) -> list[tuple[str, str]]:
    """(service, mapping) for every `ports:` entry in a generated compose file.

    Read line by line, like the data directories above: the generator writes
    one short-form mapping per line under a `ports:` key, and this has to work
    where PyYAML is not installed.
    """
    found: list[tuple[str, str]] = []
    service = ""
    indent: int | None = None
    for line in text.splitlines():
        match = _SERVICE_RE.match(line)
        if match:
            service, indent = match.group(1), None
            continue
        if line.strip() == "ports:":
            indent = len(line) - len(line.lstrip())
            continue
        if indent is None:
            continue
        entry = _PORT_ENTRY_RE.match(line)
        if entry and len(line) - len(line.lstrip()) > indent:
            found.append((service, entry.group(1)))
        elif line.strip() and not line.lstrip().startswith("#"):
            indent = None
    return found


def exposed_ports(text: str) -> list[tuple[str, str, str]]:
    """(service, mapping, why) for each port published beyond this host."""
    out: list[tuple[str, str, str]] = []
    for service, mapping in published_ports(text):
        addr = mapping_address(mapping)
        if addr is None:
            out.append((service, mapping, "no address: every interface"))
            continue
        try:
            local = is_loopback(addr)
        except ValueError:
            # ${VAR} or something else this cannot judge; say so.
            out.append((service, mapping, "address not recognised"))
            continue
        if not local:
            out.append((service, mapping, f"bound to {addr}"))
    return out


def _warn_about_exposure(cdir: Path) -> None:
    """Say so when the stack about to start is reachable from other machines.

    The ports are in the rendered YAML, not interpolated, so the file is what
    decides -- and a stack rendered before <publish-bind-addr> covered the
    guests' SSH ports publishes them on every interface whatever the fleet
    file now says. A guest from the published image accepts a key and a
    password that are both public, as a user with sudo.

    A warning, never a refusal: on a lab network it can be what was asked
    for, with <publish-bind-addr>.
    """
    try:
        text = (cdir / "docker-compose.yml").read_text()
    except OSError:
        return
    exposed = exposed_ports(text)
    if not exposed:
        return
    print("Warning: this stack publishes ports other machines can reach:",
          file=sys.stderr)
    shown = exposed[:8]
    for service, mapping, why in shown:
        print(f"           {service}  {mapping}  ({why})", file=sys.stderr)
    if len(exposed) > len(shown):
        print(f"           ... and {len(exposed) - len(shown)} more",
              file=sys.stderr)
    print(
        "         A guest from the published image accepts a key and a "
        "password that\n"
        "         are both public, as a user with sudo, and Grafana has "
        "anonymous admin.\n"
        "         Loopback is the default: re-render the stack with "
        "`qemu-tool gen-compose`,\n"
        "         or keep <publish-bind-addr> if this is deliberate.",
        file=sys.stderr,
    )


def _warn_about_root_artifacts(images: str | None, cdir: Path) -> None:
    """Name the files an earlier root-era run left behind, before they bite.

    This is the migration hazard, and it does not present as a permissions
    problem. A <vm>-nvmeN.qcow2 created by a root container is 0644
    root-owned; QEMU opens a drive read-write, so the guest does not boot at
    all. A data directory created by the daemon is 0755 root-owned and
    Prometheus crash-loops on "mkdir data/: permission denied". Both read as
    "the fleet is broken" a long way from the cause.

    A warning, never a refusal. Someone may be deliberately running a mixed
    fleet, and `up` on a stack with one stale file should still bring up the
    other thirty-one guests.
    """
    uid = os.getuid()
    offenders: list[str] = []
    if images:
        try:
            # Only the files a container creates. The backing and overlay
            # qcow2s are made by gen-vm on the host, as the caller, and a
            # fleet legitimately shares a backing image owned by someone else.
            for path in sorted(Path(images).glob("*-nvme*.qcow2")):
                if path.stat().st_uid != uid:
                    offenders.append(f"{path}  (uid {path.stat().st_uid})")
        except OSError:
            pass
    for element, path in _data_dirs(cdir):
        try:
            if path.is_dir() and path.stat().st_uid != uid:
                offenders.append(
                    f"{path}  (<{element}>, uid {path.stat().st_uid})")
        except OSError:
            continue
    if not offenders:
        return
    print(
        f"Warning: these are not owned by uid {uid}, which the containers now "
        "run as:",
        file=sys.stderr,
    )
    for line in offenders:
        print(f"           {line}", file=sys.stderr)
    print(
        "         They were probably created by a root-era run of this stack.\n"
        "         An NVMe qcow2 the guest cannot write stops it booting; a data\n"
        "         directory it cannot write crash-loops the service. Delete the\n"
        "         qcow2s (they are scratch) and chown the directories.",
        file=sys.stderr,
    )


def _precreate_data_dirs(cdir: Path) -> None:
    """Create the bind-mount targets as the caller, not as the daemon.

    Docker creates a missing bind-mount source itself, root-owned, and the
    service that then cannot write it is the one that reports the problem --
    several minutes and one confusing stack trace later. Making them here
    costs nothing and removes the "chown these three directories before your
    first run" step from the settings file entirely.
    """
    for element, path in _data_dirs(cdir):
        try:
            path.mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            # Not fatal: the service that needs it may not be in the profiles
            # being started, and a stack that is otherwise fine should come
            # up. But say what to run -- the default /var/lib/qemu-tool is
            # root-owned on every host that ever ran this as root, so this
            # fires for the ordinary operator doing nothing wrong, and a
            # bare "Permission denied" leaves them to work out the fix.
            print(
                f"Warning: could not create <{element}> at {path}: "
                f"{exc.strerror}.\n"
                f"         The service that uses it will fail to start if it "
                "is in a profile you enable.\n"
                f"         Fix: sudo mkdir -p {path} && "
                f"sudo chown {os.getuid()}:{os.getgid()} {path}",
                file=sys.stderr,
            )
    for point in _nested_mount_points(cdir):
        try:
            point.mkdir(parents=True, exist_ok=True)
        except OSError:
            # The data directory above it has already been reported, or is
            # someone else's; the runtime then makes this one, as before.
            pass


def run(
    images_dir: Path | None,
    compose_args: list[str],
    stack: str | None = None,
    xml: list[Path] | None = None,
    stack_dir: Path | None = None,
) -> None:
    if stack_dir is not None and stack is not None:
        sys.exit(
            "Error: --stack-dir and --stack select the same thing two ways.\n"
            f"       Got --stack-dir {stack_dir} and --stack {stack}; pass one."
        )
    # A rendered stack is the only way to run an overlay fleet: <vm-count> and
    # the VM names are baked into the generated YAML, not interpolated at
    # run time, so without this the committed stack ran no matter which
    # layers were passed -- the two-guest default stack silently standing in for the
    # 32-VM one just generated.
    if stack_dir is not None:
        cdir = _stack_dir(stack_dir)
        rendered = True
    else:
        discovered = _discover_stack_dir(stack)
        rendered = discovered is not None
        cdir = discovered if rendered else _compose_dir(stack or _DEFAULT_STACK)
    env = os.environ.copy()
    if images_dir is not None:
        env["VM_IMAGES_DIR"] = str(images_dir.resolve())
    cmd = ["docker", "compose"]
    # Explicit flags win. Otherwise a rendered stack has its design-time
    # values inlined at gen-compose time and records no layers, so it is
    # driven with none, which is what makes `qemu-tool compose ps` work with
    # no arguments from inside a fleet directory. A --stack-dir with no
    # provenance header was not generated by us, so it keeps the search path.
    if xml is None and rendered and _is_rendered_stack(cdir):
        layers = []
    else:
        layers = settings.find(xml)
    named = None if rendered else (stack or _DEFAULT_STACK)
    # Last, after an explicit --xml and the search path: a shipped stack's
    # own fleet file, the same fallback gen-compose renders it from.
    if not layers and named is not None:
        own = stack_fleet(named)
        if own is not None:
            layers = [own]
    fleet = FleetXml.parse_layers(layers) if layers else None
    # A rendered tree is always checked, and one rendered from a different
    # version of the layers is exactly what driving a stack directory makes
    # easy to hit, so the digest is re-hashed from the files' current bytes.
    if layers:
        _warn_if_stale(cdir, layers, named, explicit=xml is not None)
    # Through the child's environment, never a file, and only for names the
    # caller's environment does not already set.
    interpolation_env(fleet, env)
    # Every service carries `user: ${CONTAINER_USER:?...}` now, so this is
    # what makes the supported path need no configuration: unset means "run
    # the fleet as me", not "run it as root". Plain `docker compose` against
    # the same file gets the :? error instead, which says what to set.
    _apply_identity(env)
    if any(arg in _STARTING for arg in compose_args):
        _precreate_data_dirs(cdir)
        _warn_about_root_artifacts(env.get("VM_IMAGES_DIR"), cdir)
        _warn_about_exposure(cdir)
    # Belt and braces: cli._split_compose_argv already drops a user-typed "--",
    # but docker compose treats everything after a "--" as positional, so a
    # leaked separator made `-- --profile metrics up -d` bring up the default
    # services and report success -- the quiet failure, not a visible one.
    if compose_args and compose_args[0] == "--":
        compose_args = compose_args[1:]
    # After the "--" strip, so a leaked separator cannot hide the verb from
    # the teardown check, and BEFORE compose_args, because --profile is a
    # global flag that compose only accepts ahead of the subcommand.
    teardown = _all_profiles_for_teardown(compose_args)
    if teardown:
        # Said out loud. This differs from what a plain `docker compose` in
        # the same directory would do, and a silent difference between the
        # wrapper and the thing it wraps is its own trap.
        print("Tearing down every profile; pass --profile to scope it.",
              file=sys.stderr)
        cmd += teardown
    cmd += compose_args
    result = subprocess.run(cmd, cwd=cdir, env=env)
    if teardown and result.returncode == 0:
        _warn_about_survivors(cmd[:len(cmd) - len(compose_args)], cdir, env)
    sys.exit(result.returncode)
